import{store}from"@wordpress/interactivity";import"@woocommerce/stores/woocommerce/products";let productsStoreLock="I acknowledge that using a private store means my plugin will inevitably break on the next store release.",addToCartWithOptions=document.querySelector('[data-block-name="woocommerce/add-to-cart-with-options-variation-selector"]');if(addToCartWithOptions){let r=store("woocommerce/products",{},{lock:productsStoreLock}).state;document.addEventListener("wc_price_based_country:set_product_price",function(t){let o=t.detail;o&&r.productVariations&&Object.keys(o).forEach(function(t){var t=o[t],e=r.productVariations[t.id];e&&(e.price_html=t.price_html)})}),document.addEventListener("wc_price_based_country:get_product_ids",function(t){Array.isArray(t.detail)&&t.detail.push(...Object.keys(r.productVariations||{}))})}document.body.dataset["wc_price_based_country:add_to_cart_with_options_ready"]=1,document.dispatchEvent(new CustomEvent("wc_price_based_country:add_to_cart_with_options_ready"));